INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (81, 430, 'BOPP STRAW FILM', '../upload/image/20211220/20211220181501_23529.jpg', '<p><span style="font-family:Tahoma;font-size:18px;color:#009900;">BOPP STRAW FILM </span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">The film is hest sealable film and normally it is used for straw auto-packing,</span></p> <p><span style="font-family:Tahoma;font-size:18px;color:#009900;">excellenttransparent and lower anti-static . </span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">Thickness of the film: 15-40 Microns</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">Width: 90-1200MM</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">Length: 3000-9000M</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">Festure: two sides heat sealable and one side heat sealable.&nbsp;</span></p>', '2026-09-06 20:58:45');